ValidationRule.errorConditionFormula:
AND(NOT( $Setup.Org_Exceptions__c.Bypass_Validation_rules__c ), OR(
AND(
ISPICKVAL(PF_Project_Status__c, "In Progress"),
PF_Actual_End_Date__c <= TODAY()
),
AND(
ISPICKVAL(PF_Project_Status__c, "In Progress"),
ISBLANK( PF_Actual_Start_Date__c)
),
AND(
ISPICKVAL(PF_Project_Status__c, "In Progress"),
PF_Actual_Start_Date__c > TODAY()
)
)
)
